  ('ad83fea4-f770-4b10-aa03-29f7c571c188', $$Natuurkunde$$, $$VWO$$, $$Snelheidsrecord op de fiets$$, $$VWO Natuurkunde 2024-I$$),
  ('f9499b4d-44b5-48c4-af2a-ea070dafe6dc', $$Natuurkunde$$, $$VWO$$, $$Goudlokje$$, $$VWO Natuurkunde 2024-I$$),
